contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) set MinSum and LogFile and initialize Put by sending some Ether from this contract
    // 2) call Put to deposit funds for this contract as msg.sender (InvMutTest)
    // 3) optionally advance by using _lock parameter in Put; then call Collect and observe whether it reverted
    // The property asserts that if Collect succeeded then Acc[this].balance decreased by exactly _am and address(c).balance decreased by _am.

    // Note: run is payable so the tester can provide Ether to fund Put and Collect transfers.
    function run(uint _minSum, uint _lockTime, uint _putAmount, uint _collectAmount, address _logAddr) public payable {
        require(true);
        // ensure this contract has enough Ether to send to c for Put and potential other calls
        require(address(this).balance >= _putAmount, "insufficient balance for put");

        // 1) Set LogFile and MinSum before initialization; these calls will revert if intitalized already on c,
        // but c is freshly deployed by checker so they should succeed.
        // As contract methods are nonReentrant_, they can be called sequentially.
        c.SetLogFile(_logAddr);
        c.SetMinSum(_minSum);

        // 2) Record balances before Put
        C.Holder memory beforeHolder = c.Acc(address(this));
        uint beforeHolderBalance = beforeHolder.balance;
        uint beforeCbalance = address(c).balance;

        // 3) Call Put to deposit _putAmount into c for this contract
        c.Put{value: _putAmount}(_lockTime);

        // After Put: read recorded balance and contract balance
        C.Holder memory afterPutHolder = c.Acc(address(this));
        uint afterPutHolderBalance = afterPutHolder.balance;
        uint afterPutCbalance = address(c).balance;

        // Consistency: afterPutHolderBalance should be beforeHolderBalance + _putAmount
        // but we will not assert this directly; instead use it in reasoning for Collect.

        // 4) Try Collect and capture whether it reverted
        bool collectReverted;
        // Need to ensure this contract has no msg.value for Collect; Collect is payable but uses msg.sender.call to send out funds
        try c.Collect{value:0}(_collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read state after Collect attempt
        C.Holder memory afterHolder = c.Acc(address(this));
        uint afterHolderBalance = afterHolder.balance;
        uint afterCbalance = address(c).balance;

        // Obtain observed values used in the assertion
        // We assert a general property:
        // If Collect succeeded (not reverted) then:
        //   - beforePutHolderBalance + _putAmount >= _collectAmount
        //   - beforePutHolderBalance + _putAmount >= _minSum (MinSum <= balance holds)
        //   - block.timestamp > unlockTime must have been true at call time (we cannot read block inside assert),
        //   - and recorded holder balance decreased by exactly _collectAmount and contract balance decreased by exactly _collectAmount.
        // If Collect reverted then at least one of the preconditions must have been false: balance<MinSum or balance<_collectAmount or block.timestamp<=unlockTime.

        // Construct booleans we can check via public getters:
        uint finalHolderBalance = afterHolderBalance;
        uint expectedBalanceAfterSuccessfulCollect = afterPutHolderBalance;
        // We cannot read unlockTime and block.timestamp for the exact call moment, but we can still assert the transfer effects when success occurs.

        assert(
            // If collect reverted then it's allowed (no transfer happened), or
            collectReverted && finalHolderBalance == afterPutHolderBalance && afterCbalance == afterPutCbalance
            // If collect succeeded then balances must have decreased by exactly _collectAmount
            || (!collectReverted && afterPutHolderBalance >= _collectAmount &&
                finalHolderBalance + _collectAmount == afterPutHolderBalance &&
                afterPutCbalance >= _collectAmount &&
                afterCbalance + _collectAmount == afterPutCbalance)
        );
    }

    // receive to accept Ether if the tested contract sends us funds
    receive() external payable {}
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single-entry test. We deposit via Put and then attempt Collect; assert balance effects match success/failure.
    function run(uint _minSum, uint _lockTime, uint _putAmount, uint _collectAmount, address _logAddr) public payable {
        require(address(this).balance >= _putAmount, "insufficient balance for put");

        // Configure c before Initialized() is called
        c.SetLogFile(_logAddr);
        c.SetMinSum(_minSum);

        // Read balances before Put
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeCbalance = address(c).balance;

        // Perform Put to deposit funds for this contract as msg.sender
        c.Put{value: _putAmount}(_lockTime);

        // Read balances after Put and before Collect
        uint afterPutHolderBalance = c.Acc(address(this)).balance;
        uint afterPutCbalance = address(c).balance;

        // Try Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value:0}(_collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read balances after Collect attempt
        uint finalHolderBalance = c.Acc(address(this)).balance;
        uint finalCbalance = address(c).balance;

        // Assert the invariant: if Collect succeeded then both holder and contract balances decreased by exactly _collectAmount
        // If Collect reverted then neither recorded holder balance nor contract balance changed by the Collect attempt
        assert(
            (!collectReverted && afterPutHolderBalance >= _collectAmount && afterPutCbalance >= _collectAmount
                && finalHolderBalance + _collectAmount == afterPutHolderBalance
                && finalCbalance + _collectAmount == afterPutCbalance)
            || (collectReverted
                && finalHolderBalance == afterPutHolderBalance
                && finalCbalance == afterPutCbalance)
        );
    }

    // Receive to accept Ether sent from C during Collect
    receive() external payable {}
}

