contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising Put and observing its observable effects.
    // Params: _lockTime controls the holder.unlockTime update; _putAmount is the Ether to send to Put;
    // _minSum and _logAddr initialize contract so Put can log without revert from uninitialized LogFile.
    function run(uint _minSum, uint _lockTime, uint _putAmount, address _logAddr) public payable {
        // Ensure this test contract has enough Ether to send the deposit
        require(address(this).balance >= _putAmount);

        // Initialize c so Put's call to LogFile.AddMessage won't fail due to a zero address.
        c.SetLogFile(_logAddr);
        c.SetMinSum(_minSum);
        c.Initialized();

        // Read holder recorded balance and contract balance before Put
        (uint beforeBalance, ) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Call Put and record whether it reverted
        bool putReverted;
        try c.Put{value: _putAmount}(_lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read balances after Put attempt
        (uint afterBalance, ) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General invariant to assert:
        // - If Put reverted: neither the recorded holder balance nor contract balance increased.
        // - If Put succeeded: contract balance increased by exactly _putAmount, and the recorded holder.balance did not decrease and is at least beforeBalance + _putAmount.
        // (We avoid subtraction that could underflow inside the assert by using additive comparisons.)
        assert(
            (putReverted
                && afterBalance == beforeBalance
                && afterCbal == beforeCbal)
            || (
                !putReverted
                && afterCbal == beforeCbal + _putAmount
                && afterBalance >= beforeBalance
                && afterBalance >= beforeBalance + _putAmount
            )
        );
    }

    // Allow receiving Ether when c calls back on this contract during Collect (not used here but present for completeness)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that drives contract and asserts the invariant
    function run(uint lockTimePut, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "need funds for put");
        // make sure MinSum is zero so Collect can potentially succeed (since MinSum default is 0)
        // Note: SetMinSum can only be called before Initialized(); this fresh c allows it.
        c.SetMinSum{value:0}(0);

        // record balances before Put
        uint beforeContractBal = address(c).balance;
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        // perform Put sending Ether to c
        c.Put{value: putAmount}(lockTimePut);

        // read balances after Put
        uint afterContractBalPut = address(c).balance;
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        // Ensure the Put increased both c balance and the recorded holder balance by putAmount
        // (this is a necessary condition for meaningful Collect semantics)
        assert(afterContractBalPut == beforeContractBal + putAmount);
        assert(afterBalance == beforeBalance + putAmount);

        // now attempt Collect; record state before Collect
        uint beforeContractBal2 = address(c).balance;
        (uint beforeUnlockTime2, uint beforeBalance2) = c.Acc(address(this));

        bool reverted;
        // Collect may revert if unlockTime not passed or other conditions; catch that
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read state after Collect attempt
        uint afterContractBal = address(c).balance;
        (uint afterUnlockTime2, uint afterBalance2) = c.Acc(address(this));

        // General rule: if Collect succeeded (not reverted) then the holder balance decreases by exactly collectAmount
        // and contract balance decreases by exactly collectAmount; otherwise both balances unchanged.
        assert(
            (!reverted && afterBalance2 + collectAmount == beforeBalance2 && afterContractBal + collectAmount == beforeContractBal2)
            || (reverted && afterBalance2 == beforeBalance2 && afterContractBal == beforeContractBal2)
        );
    }

    receive() external payable { }
}

