        } catch {
            collectReverted = true;
        }

        // Reads after collect attempt
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assertion: If Collect succeeded then holder balance decreased by exactly collectAmount
        // and contract balance decreased by at least collectAmount (transfer might fail internally but Collect only claims success when transfer succeeded).
        // If Collect reverted then balances did not increase compared to just-after-put values.
        assert(
            collectReverted
            ? (afterBalance >= midBalance && afterContractBal >= midContractBal)
            : (midBalance >= collectAmount && afterBalance + collectAmount == midBalance && midContractBal >= afterContractBal && midContractBal - afterContractBal >= collectAmount)
