contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will simulate a depositor by calling Put/fallback from this contract (msg.sender for c is this contract)
    // Inputs:
    // initial_deposit: amount to deposit into c via Put (sent as value)
    // lockTime: lock duration passed to Put
    // collect_amt: amount to attempt to Collect
    // setMin: value to set MinSum (must be done before Initialized)
    function run(uint initial_deposit, uint lockTime, uint collect_amt, uint setMin) public payable {
        require(address(this).balance >= initial_deposit + 1 wei);

        // 1) Ensure MinSum is set to setMin (contract is fresh so intitalized is false)
        // Call SetMinSum from this contract (this is allowed because checker's c is fresh)
        c.SetMinSum(setMin);

        // 2) Record c balance and holder balance before deposit
        uint before_c_bal = address(c).balance;
        (uint before_unlock, uint before_holder_bal) = getHolderState();

        // 3) Make a deposit by calling Put with value initial_deposit
        c.Put{value: initial_deposit}(lockTime);

        // 4) After deposit read balances
        uint mid_c_bal = address(c).balance;
        (uint mid_unlock, uint mid_holder_bal) = getHolderState();

        // 5) Try to move time forward so that block.timestamp > unlockTime by calling Collect with 0 if possible.
        // We cannot change block.timestamp in tests, but we allow both branches: Collect may revert or succeed.
        bool reverted;
        try c.Collect{value: 0}(collect_amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after_c_bal = address(c).balance;
        (uint after_unlock, uint after_holder_bal) = getHolderState();

        // The general rule to assert:
        // If Collect succeeded (not reverted) then:
        //  - before_holder_bal >= setMin
        //  - before_holder_bal >= collect_amt
        //  - block.timestamp > mid_unlock (we cannot read timestamp here), but Collect success implies those conditions
        //  - holder balance decreased by exactly collect_amt
        //  - c's balance decreased by exactly collect_amt
        // Otherwise (if reverted) at least one precondition was false OR no transfer happened.

        // We express this as a logical implication using only observable values.
        // If not reverted then balances must have decreased by collect_amt.
        // If reverted then either holder didn't meet numeric requirements (mid_holder_bal < setMin || mid_holder_bal < collect_amt) or there was no change in balances.

        assert(
            (!reverted && after_holder_bal + collect_amt == mid_holder_bal && mid_c_bal >= collect_amt && after_c_bal + collect_amt == mid_c_bal)
            || (reverted && (mid_holder_bal < setMin || mid_holder_bal < collect_amt || (after_holder_bal == mid_holder_bal && after_c_bal == mid_c_bal)))
        );
    }

    // helper to read Acc[this].unlockTime and Acc[this].balance via public getter Acc(address) returns (unlockTime,balance)
    function getHolderState() internal returns (uint unlockTime, uint balance) {
        // The public mapping Acc has an auto-generated getter with signature (address) returns (uint,uint)
        (unlockTime, balance) = c.Acc(address(this));
    }

    receive() external payable { }
}

