        }

        // Read recorded holder state and c balance before attempting Collect
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Attempt Collect: call with _am and capture whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(_am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read recorded holder state and c balance after Collect attempt
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If Collect succeeded then:
        //  - c's on-chain balance decreased by exactly _am
        //  - recorded balance for this address decreased by exactly _am
        // Otherwise (Collect reverted) we only require that recorded balance and c balance did not decrease due to Collect
        // However because Put itself might have reverted, we must account: if Put reverted then beforeBalance equals afterBalance and c balance unchanged.

        // Assert a general rule combining outcomes:
        // If Collect did not revert then (cBalBefore - cBalAfter == _am) and (beforeBalance - afterBalance == _am).
        // If Collect reverted then either nothing changed (balances equal) or Collect couldn't proceed due to insufficient conditions; we assert that c's balance did not decrease and recorded balance did not decrease.

        assert(
            (!collectReverted && cBalBefore == cBalAfter + _am && beforeBalance == afterBalance + _am)
            || (collectReverted && cBalBefore == cBalAfter && beforeBalance == afterBalance)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to drive Put and Collect. amountPut funds the contract when calling Put.
    // collectAmt is the requested amount to Collect.
    function run(uint lockTime, uint amountPut, uint collectAmt) public payable {
        require(address(this).balance >= amountPut, "insufficient test balance for Put");
        // initial observations
        uint beforeContractBal = address(c).balance;
        // ensure MinSum is some nonzero value and log is set so Put/Collect won't revert due to uninitialized LogFile
        // Use SetLogFile and SetMinSum before Initialized() — these do not change contract balance.
        // These calls must be top-level state-changing calls.
        c.SetLogFile(address(0));
        c.SetMinSum(1);
        // Make a Put call funding the contract from this test contract
        c.Put{value: amountPut}(lockTime);
        uint afterPutContractBal = address(c).balance;
        // Read public holder info for this contract (msg.sender in c is this test contract)
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));

        // Try Collect and record whether it reverted; capture contract balance after Collect attempt.
        bool reverted;
        uint afterCollectContractBal;
        // Collect is payable in source but we call without sending value
        try c.Collect(collectAmt) {
            reverted = false;
            afterCollectContractBal = address(c).balance;
        } catch {
            reverted = true;
            afterCollectContractBal = address(c).balance;
        }

        // If Collect succeeded (not reverted), then it must satisfy the contract's on-success preconditions:
        // prior holder balance >= MinSum, prior holder balance >= collectAmt, and block.timestamp > unlockTimeBefore.
        // Otherwise (if one of those preconditions was false), Collect must not have decreased c's balance.
        // We assert a general implication capturing that: if Collect did not revert then those three conditions held;
        // and if Collect reverted or conditions didn't hold then contract balance did not decrease.
        // Access MinSum and contract balance via public surface
        uint minSum = c.MinSum();

        bool condsHold = (balanceBefore >= minSum) && (balanceBefore >= collectAmt) && (block.timestamp > unlockTimeBefore);

        // build the final asserted property
        // Case A: not reverted => condsHold
        // Case B: reverted OR not condsHold => afterCollectContractBal >= afterPutContractBal (no decrease)
        assert((!reverted ? condsHold : true) && ((reverted || !condsHold) ? (afterCollectContractBal >= afterPutContractBal) : true));
    }

    // Allow receiving Ether for test funding
    receive() external payable {}
}
